if(TV)document.body.classList.add('tv');
var win=(function(){var w=qs.get('win')||null;try{w=w||localStorage.getItem('salesboard_win')}catch(e){}return ['30','45','60','90','all'].indexOf(w)>=0?w:'45'})();var D=null,keyCache={},fper='ytd',tvIdx=0,tvTimer=null,progTimer=null,sortKey='risk_usd',openDes={};
var $=function(id){return document.getElementById(id)};
function esc(s){return String(s==null?'':s).replace(/[&<>"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]})}
function m(v){if(v==null)return '—';var a=Math.abs(v),s=v<0?'-':'';if(a>=1e6)return s+'$'+(a/1e6).toFixed(2)+'M';if(a>=1e4)return s+'$'+Math.round(a/1e3)+'K';if(a>=1e3)return s+'$'+(a/1e3).toFixed(1)+'K';return s+'$'+Math.round(a)}
