// ── helpers
function delta(cur,prev,o){o=o||{};if(prev==null||prev===0||cur==null)return '<span class="neu">—</span>';var d=cur-prev,pc=Math.round(d/Math.abs(prev)*100);if(o.points){var dp=(cur-prev)*100;var good=o.lower?dp<0:dp>0;return '<span class="'+(Math.abs(dp)<.5?'neu':good?'up':'dn')+'">'+(dp>=0?'▲':'▼')+' '+Math.abs(dp).toFixed(1)+' pts '+(o.lab||'')+'</span>'}
 var good=o.lower?d<0:d>0;return '<span class="'+(pc===0?'neu':good?'up':'dn')+'">'+(d>=0?'▲':'▼')+' '+Math.abs(pc)+'% '+(o.lab||'')+'</span>'}
function tile(lab,big,small,sub){return '<div class="card tile"><div class="lab">'+lab+'</div><div class="big">'+big+'</div><div class="sm">'+(small||'')+'</div>'+(sub?'<div class="sm">'+sub+'</div>':'')+'</div>'}
function rateCls(r,net,team,band){band=band||.03;if(r==null||net<20)return 'rn';return r>=team+band?'rg':r<=team-band?'rr':'rn'}
