function tierBar(t,h){var tot=0;TIERS.forEach(function(x){tot+=(t[x[0]]||0)});if(!tot)return '<div class="hbar"></div>';return '<div class="hbar" style="height:'+(h||14)+'px">'+TIERS.map(function(x){return '<i class="c-'+x[0]+'" style="width:'+((t[x[0]]||0)/tot*100)+'%" title="'+x[1]+' '+m(t[x[0]]||0)+'"></i>'}).join('')+'</div>'}
function dupTag(L,i){var k=function(x){return [x.name,x.des,Math.round(x.usd),x.stage].join('|')},me=k(L[i]),n=0,idx=0;for(var j=0;j<L.length;j++)if(k(L[j])===me){n++;if(j<=i)idx++}if(n<2)return '';var x=L[i];return x.age!=null?' · appt '+x.age+'d ago':' · #'+idx}
