 function arc(f,col,wd){var a=pt(0,R),b=pt(f,R);return '<path d="M'+a[0]+' '+a[1]+' A'+R+' '+R+' 0 '+(f>.5?1:0)+' 1 '+b[0]+' '+b[1]+'" fill="none" stroke="'+col+'" stroke-width="'+wd+'" stroke-linecap="round"/>'}
 var t1=pt(ex,R-16),t2=pt(ex,R+12),good=q.gap>=0;
