 var cm=Ms[Ms.length-1],tfin=P.cmp?P.cmp.typ_final:0,max=0;
 Ms.forEach(function(x){if(mode==='usd'){max=Math.max(max,x.final)}});if(mode==='usd'&&P.cmp)max=Math.max(max,P.cmp.typ_final);
