 for(var g=0;g<=ng;g++){var v=max*g/ng,y=Y(v);s+='<line x1="'+pl+'" x2="'+(w-pr)+'" y1="'+y+'" y2="'+y+'" stroke="#e8e4d9"/><text x="'+(pl-5)+'" y="'+(y+fs/3)+'" text-anchor="end" font-size="'+fs+'" fill="#667085">'+(mode==='usd'?m(v):Math.round(v*100)+'%')+'</text>'}
 [10,20].forEach(function(d){s+='<line x1="'+X(d)+'" x2="'+X(d)+'" y1="'+pt+'" y2="'+(h-pb)+'" stroke="#b8b2a0" stroke-dasharray="2 3"/>'});
 s+='<rect x="'+X(22)+'" y="'+pt+'" width="'+(X(31)-X(22))+'" height="'+(h-pt-pb)+'" fill="#14171c" opacity=".035"/>';
