 s+='<text x="'+(X(10)+3)+'" y="'+(pt+fs)+'" font-size="'+(fs-1)+'" fill="#8a8470">day 10</text><text x="'+(X(20)+3)+'" y="'+(pt+fs)+'" font-size="'+(fs-1)+'" fill="#8a8470">day 20</text><text x="'+(X(22)+3)+'" y="'+(h-pb-5)+'" font-size="'+(fs-1)+'" fill="#8a8470">last 10 days</text>';
