// ── MONTH FOCUS: path to goal (all numbers pre-computed in refresh.py: D.focus)
function fxWaterfall(F){var tgt=F.target,rows=[],cum=0;
 function row(cls,lb,sub,val,subv,from,w){return '<div class="wfr"><div class="lb">'+lb+(sub?'<small>'+sub+'</small>':'')+'</div><div class="tr"><i class="'+cls+'" style="left:'+(from/tgt*100).toFixed(2)+'%;width:'+Math.max(w/tgt*100,.4).toFixed(2)+'%"></i><span class="goal"></span></div><div class="vv">'+val+(subv?'<small>'+subv+'</small>':'')+'</div></div>'}
 var h='<div class="wf">';h+=row('c-sold','Sold (Final)',(F.sales-F.pend_n)+' sales',mf(F.sold_final),p(F.sold_final/tgt,0)+' of goal',0,F.sold_final);h+=row('c-pend','+ Sold, pending Final',F.pend_n+' designer-sold deals','+'+mf(F.pend_usd),'counted as sold: '+mf(F.sold)+' total',F.sold_final,F.pend_usd);cum=F.sold;
 var st=(F.tiers.map(function(t){return [{hot:'c-hot',live:'c-live',stale:'c-stale',cold:'c-cold'}[t.key],t]}));
 st.forEach(function(x){var t=x[1],lo=t.lo!=null?t.lo:t.exp;h+=row(x[0],'+ '+esc(t.name),t.n+' deals · '+m(t.face)+' open',(t.exp>=0?'+':'')+m(t.exp),'range '+m(t.lo)+'–'+m(t.hi),cum,t.exp);cum+=t.exp});
 h+=row('c-up','+ Appointments still to run',F.upcoming.n+' booked through '+esc(F.month_end),'+'+m(F.upcoming.exp),'≈'+Math.round(F.upcoming.p_h*100)+'% close × '+mf(F.upcoming.avg_sale),cum,F.upcoming.exp);cum+=F.upcoming.exp;
 h+='<div class="wfr tot"><div class="lb">= Previous expected finish<small>open deals + booked appts only (kept as a component)</small></div><div class="tr"><i class="c-exp" style="left:0;width:'+Math.min(cum/tgt*100,100).toFixed(2)+'%"></i><span class="goal"></span></div><div class="vv">'+m(cum)+'<small>'+p(cum/tgt,0)+' of goal</small></div></div>';
 var PP=D.pace;if(PP){var adj=(PP.B.usd-PP.B.prev)+(PP.C.usd-PP.C.prev);
  h+=row('c-adj','+ Month-end timing of open odds','odds measured at the same days-to-month-end',(adj>=0?'+':'−')+m(Math.abs(adj)),'sales cluster late in the month',Math.min(cum,tgt),Math.max(Math.min(Math.abs(adj),tgt-cum),0));cum+=adj;
  h+=row('c-new','+ New leads & appointments (in-month)',n(PP.D.n_opps)+' opps still to arrive at recent rates','+'+m(PP.D.usd),'lag-adjusted; spill '+m(PP.spill.D)+' next month',Math.min(cum,tgt),Math.max(Math.min(PP.D.usd,tgt-cum),0));cum+=PP.D.usd;
  h+='<div class="wfr tot"><div class="lb">= TRUE PACE finish<small>low '+m(PP.low)+' · high '+m(PP.high)+'</small></div><div class="tr"><i class="c-exp2" style="left:0;width:'+Math.min(cum/tgt*100,100).toFixed(2)+'%"></i><span class="goal"></span></div><div class="vv">'+m(cum)+'<small>'+p(cum/tgt,0)+' of goal</small></div></div>';
  h+=row('c-gap','Shortfall: gap to create','even at true pace',m(Math.max(tgt-cum,0)),'needs better closing, not just leads',Math.min(cum,tgt),Math.max(tgt-cum,0))}
 else h+=row('c-gap','Shortfall: gap to create','even after all of the above',m(F.shortfall),'needs new appts + closes',Math.min(cum,tgt),Math.max(tgt-cum,0));
 return h+'</div><div class="fxleg"><span style="--c:#000;border-radius:0">┆ dashed line = month goal '+mf(tgt)+'</span><span style="--c:#0d8a4e">green = sold</span><span style="--c:#4fb37d">hatch-green = pending Final</span><span style="--c:#6b6b6b">black-grey = stale, needs a push</span><span style="--c:#c62828">red = shortfall</span></div>'}
