// ── GOAL-BACK PLAN (D.plan, month-scoped; built in refresh.py from goal_plan.json): per-designer October targets + daily path
function planOf(name){var P=D.plan;if(!P)return null;for(var i=0;i<P.designers.length;i++)if(P.designers[i].name===name)return P.designers[i];return null}
function planPath(){var P=D.plan,b=P.baseline.sold,d0=P.daily[0].day,pts=[[d0-1,b]];P.daily.forEach(function(d){pts.push([d.day,d.cum_month])});return pts}
function planMini(o){var P=D.plan,w=o.w||640,h=o.h||170,fs=o.fs||11,pl=50,pr=70,pt=14,pb=22,pts=planPath(),d0=pts[0][0],d1=pts[pts.length-1][0],ymax=P.month_goal*1.06;
 function X(d){return pl+(w-pl-pr)*(d-d0)/(d1-d0)}function Y(v){return pt+(h-pt-pb)*(1-v/ymax)}
 var s='<svg viewBox="0 0 '+w+' '+h+'" width="100%" role="img" aria-label="Daily path to the month goal" style="display:block">';
 for(var g=0;g<=4;g++){var v=ymax*g/4,y=Y(v);s+='<line x1="'+pl+'" x2="'+(w-pr)+'" y1="'+y+'" y2="'+y+'" stroke="#eee"/><text x="'+(pl-4)+'" y="'+(y+3)+'" text-anchor="end" font-size="'+fs+'" fill="#889">'+m(v)+'</text>'}
 pts.forEach(function(q){s+='<text x="'+X(q[0])+'" y="'+(h-6)+'" text-anchor="middle" font-size="'+(fs-1)+'" fill="#889">'+q[0]+'</text>'});
 s+='<path d="M'+pts.map(function(q){return X(q[0]).toFixed(1)+' '+Y(q[1]).toFixed(1)}).join('L')+'" fill="none" stroke="#7b3fa0" stroke-width="2.4" stroke-dasharray="6 3"/>';
 P.checkpoints.forEach(function(c){s+='<circle cx="'+X(c.day)+'" cy="'+Y(c.cum_month)+'" r="5" fill="#7b3fa0" stroke="#fff" stroke-width="1.5"/><text x="'+(X(c.day)-6)+'" y="'+(Y(c.cum_month)-8)+'" text-anchor="end" font-size="'+fs+'" font-weight="700" fill="#7b3fa0">'+esc(c.label)+' '+m(c.cum_month)+'</text>'});
 var td=Math.min(Math.max(+D.meta.today.slice(8,10),d0),d1);s+='<circle cx="'+X(td)+'" cy="'+Y(P.team_sold)+'" r="5.5" fill="#000" stroke="#fff" stroke-width="2"/><text x="'+(X(td)+8)+'" y="'+(Y(P.team_sold)+4)+'" font-size="'+(fs+1)+'" font-weight="800" fill="#000">sold '+m(P.team_sold)+'</text>';
 return s+'</svg>'}
function planCard(){var P=D.plan;if(!P)return '';var gp=P.team_gap_path,st=gp<=0?'pos':(gp<P.path_now*0.03?'':'neg');
 var h='<div class="card fx plan"><h3>🎯 October targets <small>goal-back plan (CEO Coach, approved by Andrew) · target = sold through Oct 18 + remaining quota</small></h3>'+
  '<div class="plk"><div><span>Team sold</span><b>'+m(P.team_sold)+'</b></div><div><span>On path now</span><b>'+m(P.path_now)+'</b></div><div><span>'+(gp>0?'Behind path':'Ahead of path')+'</span><b class="'+st+'">'+m(Math.abs(gp))+'</b></div>'+P.checkpoints.map(function(c){return '<div><span>'+esc(c.label)+(c.day===31?' goal':'')+'</span><b>'+m(c.cum_month)+'</b></div>'}).join('')+'</div>'+
  planMini({w:TV?900:640,h:TV?190:170,fs:TV?13:11})+
  '<div class="pll hd"><span>Designer</span><span>Sold vs October target · ▏ on path now</span><span>Sold / target</span><span>Gap</span></div><div class="plg">';
 P.designers.forEach(function(r){var mx=Math.max(r.target,r.sold)||1;h+='<div class="pll"><div class="nm">'+esc(r.name)+'</div><div class="b1" title="sold vs October target"><i style="width:'+Math.min(100,r.sold/mx*100).toFixed(1)+'%"></i><u style="left:'+Math.min(100,r.pace_now/mx*100).toFixed(1)+'%"></u></div><div class="t"><b class="'+r.status+'">'+m(r.sold)+'</b> / '+m(r.target)+'</div><div class="t"><b class="'+(r.gap<=0?'pos':'')+'">'+(r.gap<=0?'hit +'+m(-r.gap):m(r.gap))+'</b></div></div>'});
 h+='</div><div class="note" style="margin-top:4px">Plan buckets: '+P.buckets.map(function(b){return esc(b.name)+' '+m(b.quota)}).join(' · ')+'.'+(P.unplanned_sold.length?' Sold this month by people without a plan target: '+P.unplanned_sold.filter(function(u){return u.sold>0}).map(function(u){return esc(u.name)+' '+m(u.sold)}).join(', ')+'.':'')+' Green = at or above the daily path, red = behind by more than 10% of the plan since Oct 18, black = near or too early to judge. Month goal stays '+m(P.month_goal)+'.</div></div>';
 return h}
