 var A='<div class="fxtop"><div class="card fx">'+fxHead(F,'🎯 Path to the '+esc(F.label.split(' ')[0])+' goal')+fxKpis(F)+fxWaterfall(F)+fxWeights(F)+'</div><div class="card fx"><h3>👤 Owner: where you spend time <small>5 actions, $ attached</small></h3>'+fxOwner(F)+'</div></div>';
